import sys

def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    rows = data[2:2 + n]
    INF = 10 ** 9
    ev = (m + 1) // 2
    od = m // 2
    prev = None
    for r in rows:
        ce = [0] * 26
        co = [0] * 26
        for j, ch in enumerate(r):
            if j % 2 == 0:
                ce[ord(ch) - 65] += 1
            else:
                co[ord(ch) - 65] += 1
        if prev is None:
            M = [[0] * 26 for _ in range(26)]
        else:
            R = [[INF] * 26 for _ in range(26)]
            for a in range(26):
                row = prev[a]
                m1 = m2 = INF
                i1 = -1
                for b in range(26):
                    v = row[b]
                    if v < m1:
                        m2 = m1
                        m1 = v
                        i1 = b
                    elif v < m2:
                        m2 = v
                for b in range(26):
                    R[a][b] = m2 if b == i1 else m1
            M = [[INF] * 26 for _ in range(26)]
            for b in range(26):
                m1 = m2 = INF
                i1 = -1
                for a in range(26):
                    v = R[a][b]
                    if v < m1:
                        m2 = m1
                        m1 = v
                        i1 = a
                    elif v < m2:
                        m2 = v
                for a in range(26):
                    M[a][b] = m2 if a == i1 else m1
        cur = [[INF] * 26 for _ in range(26)]
        for a in range(26):
            for b in range(26):
                if a != b:
                    cost = (ev - ce[a]) + (od - co[b])
                    cur[a][b] = min(INF, cost + M[a][b])
        prev = cur
    print(min(min(row) for row in prev))

main()

