pal = sorted(set(''.join(rows)))
for c in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ':
    if len(pal) >= 7:
        break
    if c not in pal:
        pal.append(c)
valid = []
for t in product(pal, repeat=m):
    if len(set(t)) <= 2 and all(t[j] != t[j + 1] for j in range(m - 1)):
        valid.append(t)
dp = {t: sum(1 for x, y in zip(t, rows[0]) if x != y) for t in valid}
for r in rows[1:]:
    nd = {}
    for t in valid:
        c = sum(1 for x, y in zip(t, r) if x != y)
        best = min(v for p, v in dp.items() if all(x != y for x, y in zip(p, t)))
        nd[t] = best + c
    dp = nd
print(min(dp.values()))

